async function buildWeeklyScheduleSegmentsSnapshot(env, ts, cw, contract, curFin, options = {}) {
  const round2 = roundMoney2HalfAwayExact;
  const pc = payChargeFromContract(contract);
  const pay = pc?.pay || null;
  const chg = pc?.charge || null;
  const method = pc?.method || contract?.pay_method_snapshot || null;

  const {
    outbox_id = null,
    write_now = false,
    hr_eff_flags = null,
    hr_preloaded_shifts = null,

    // ✅ NEW: HR weekly validation status (controls when we overwrite refs from import)
    hr_validation_status = null,
    hr_validation_reason_code = null,
    hr_validation_source_kind = null,

    // ✅ allow caller to pass SQL policy (ctx.out_policy) to avoid any REST policy loads
    policy_override = null,

    // Server-only protected-hours preview: calculate a complete candidate-pay
    // target without copying invoice-locked source segments into that target.
    // It is never permitted on a writing TSFIN call.
    ignore_locked_segments_for_preview = false,
    retain_protected_next_preview_facts = false
  } = (options && typeof options === 'object') ? options : {};

  if (ignore_locked_segments_for_preview === true && write_now === true) {
    throw new Error('PROTECTED_TARGET_PREVIEW_MUST_NOT_WRITE_TSFINS');
  }
  if (retain_protected_next_preview_facts === true
      && (write_now !== false || ignore_locked_segments_for_preview !== true)) {
    throw new Error('PROTECTED_NEXT_FACTS_REQUIRE_NONWRITING_PREVIEW');
  }

  if (!pay || !chg) {
    throw new Error('CONTRACT_RATES_MISSING');
  }

  // ─────────────────────────────────────────────────────────────
  // ✅ Stable segment identity helpers
  // ─────────────────────────────────────────────────────────────
  const _normStr = (v) => (v == null ? '' : String(v).trim());
  const _normNumInt = (v, d = 0) => {
    const n = Number(v);
    return Number.isFinite(n) ? n : d;
  };

  // FNV-1a 32-bit hash (deterministic, fast, no async crypto)
  const _hash32 = (s) => {
    let h = 0x811c9dc5;
    for (let i = 0; i < s.length; i++) {
      h ^= s.charCodeAt(i);
      h = Math.imul(h, 0x01000193);
    }
    return (h >>> 0).toString(16).padStart(8, '0');
  };

  const _stableSegKey = (segObj) => {
    if (!segObj || typeof segObj !== 'object') return '';

    // Prefer stable upstream IDs if available
    const shiftId =
      _normStr(segObj.shift_id) ||
      _normStr(segObj.hr_shift_id) ||
      _normStr(segObj.source_shift_id) ||
      _normStr(segObj.rota_shift_id) ||
      _normStr(segObj.import_shift_id);

    if (shiftId) return `shift:${shiftId}`;

    const date = _normStr(segObj.date);

    // ✅ IMPORTANT: prefer local start/end first (keeps stable IDs aligned to schedule JSON)
    const localTimes = candidateScheduleLocalTimeAliases(segObj);
    const start =
      localTimes.start ||
      _normStr(segObj.start_utc) ||
      _normStr(segObj.start_iso) ||
      _normStr(segObj.startUtc);

    const end =
      localTimes.end ||
      _normStr(segObj.end_utc) ||
      _normStr(segObj.end_iso) ||
      _normStr(segObj.endUtc);

    const breakMins = _normNumInt(segObj.break_mins ?? segObj.break_minutes ?? 0, 0);

    const fallbackSid = _normStr(segObj.segment_id);
    if (!start && !end && !date) return fallbackSid;

    return `d:${date}|s:${start}|e:${end}|b:${breakMins}`;
  };

  const _stableSegId = (tsId, segKey) => {
    const k = _normStr(segKey);
    if (!k) return `ts:${tsId}:unknown`;
    return `ts:${tsId}:${_hash32(k)}`;
  };

  // ─────────────────────────────────────────────────────────────
  // ✅ Local-time → UTC ISO helpers
  // Europe/London uses the canonical strict interval-resolution model.
  // Non-London timezones preserve the existing local→UTC fallback behaviour.
  // ─────────────────────────────────────────────────────────────
  const _addDaysYmd = (ymd, addDays) => {
    const s = String(ymd || '').slice(0, 10);
    if (!/^\d{4}-\d{2}-\d{2}$/.test(s)) return null;
    const [yy, mm, dd] = s.split('-').map(Number);
    const dt = new Date(Date.UTC(yy, mm - 1, dd));
    dt.setUTCDate(dt.getUTCDate() + Number(addDays || 0));
    return dt.toISOString().slice(0, 10);
  };

  const _tzParts = (dateObj, tzId) => {
    const fmt = new Intl.DateTimeFormat('en-GB', {
      timeZone: tzId,
      year: 'numeric',
      month: '2-digit',
      day: '2-digit',
      hour: '2-digit',
      minute: '2-digit',
      hour12: false
    });
    const parts = fmt.formatToParts(dateObj);
    const m = {};
    for (const p of parts) m[p.type] = p.value;
    return {
      y: Number(m.year),
      mo: Number(m.month),
      d: Number(m.day),
      h: Number(m.hour),
      mi: Number(m.minute)
    };
  };

  const _localYmdHmToUtcIso = (ymd, hhmm, tzId) => {
    const sY = String(ymd || '').slice(0, 10);
    const sT = String(hhmm || '').trim();
    if (!/^\d{4}-\d{2}-\d{2}$/.test(sY)) return null;
    const m = sT.match(/^(\d{2}):(\d{2})/);
    if (!m) return null;

    const [yy, mm, dd] = sY.split('-').map(Number);
    const hh = Number(m[1]);
    const mi = Number(m[2]);

    // desired local components treated as UTC (initial reference)
    const desiredAsUtcMs = Date.UTC(yy, mm - 1, dd, hh, mi, 0, 0);

    // pass 1: get offset at the guessed UTC time
    const guess1 = new Date(desiredAsUtcMs);
    const p1 = _tzParts(guess1, tzId);
    const asUtcOfParts1 = Date.UTC(p1.y, p1.mo - 1, p1.d, p1.h, p1.mi, 0, 0);
    const offsetMs1 = asUtcOfParts1 - guess1.getTime();
    const utcMs1 = desiredAsUtcMs - offsetMs1;

    // pass 2: refine offset at the refined UTC time (DST boundary safety)
    const guess2 = new Date(utcMs1);
    const p2 = _tzParts(guess2, tzId);
    const asUtcOfParts2 = Date.UTC(p2.y, p2.mo - 1, p2.d, p2.h, p2.mi, 0, 0);
    const offsetMs2 = asUtcOfParts2 - guess2.getTime();
    const utcMs2 = desiredAsUtcMs - offsetMs2;

    return new Date(utcMs2).toISOString();
  };

  const _pickTzId = () => {
    try {
      const tz = (policy_override && typeof policy_override === 'object')
        ? String(policy_override.timezone_id || '').trim()
        : '';
      return tz || 'Europe/London';
    } catch {
      return 'Europe/London';
    }
  };

  const tzId = _pickTzId();

  const _isIsoLike = (s) => !!normalisePostgresTimestampIso(s);

  const _uniqueLocalUtcCandidates = (ymd, hhmm) => {
    const out = [];
    const seen = new Set();

    const pushIso = (iso) => {
      if (!iso) return;
      const ms = new Date(iso).getTime();
      if (!Number.isFinite(ms)) return;
      const normIso = new Date(ms).toISOString();
      if (seen.has(normIso)) return;
      seen.add(normIso);
      out.push({ iso: normIso, ms });
    };

    pushIso(ukLocalToUtcISO(ymd, hhmm, { prefer: 'earlier' }));
    pushIso(ukLocalToUtcISO(ymd, hhmm, { prefer: 'later' }));

    out.sort((a, b) => a.ms - b.ms);
    return out;
  };

  const _scheduleEntryToUtcRange = (seg) => {
    const date = String(seg?.date || '').trim();
    if (!date) return { startUtcIso: null, endUtcIso: null, error: 'Schedule segment date is required' };

    const startIsoRaw = seg?.start_utc || seg?.start_iso || seg?.startUtc || null;
    const endIsoRaw   = seg?.end_utc   || seg?.end_iso   || seg?.endUtc   || null;
    const startIso = normalisePostgresTimestampIso(startIsoRaw);
    const endIso = normalisePostgresTimestampIso(endIsoRaw);
    if (startIso && endIso && _isIsoLike(startIsoRaw) && _isIsoLike(endIsoRaw)) {
      const startMs = new Date(startIso).getTime();
      const endMs   = new Date(endIso).getTime();
      if (!Number.isFinite(startMs) || !Number.isFinite(endMs) || endMs <= startMs) {
        return { startUtcIso: null, endUtcIso: null, error: `Invalid UTC shift range on ${date}` };
      }
      return {
        startUtcIso: new Date(startMs).toISOString(),
        endUtcIso: new Date(endMs).toISOString(),
        error: null
      };
    }

    const { start: startHH, end: endHH } = candidateScheduleLocalTimeAliases(seg);
    if (!startHH || !endHH) {
      return { startUtcIso: null, endUtcIso: null, error: `Shift start/end must both be set for ${date}` };
    }

    const sMin = parseHHMM(startHH);
    const eMin = parseHHMM(endHH);
    if (sMin == null || eMin == null) {
      return { startUtcIso: null, endUtcIso: null, error: `Invalid HH:MM in actual_schedule_json for ${date}` };
    }
    if (sMin === eMin) {
      return { startUtcIso: null, endUtcIso: null, error: `Shift start and end cannot be the same on ${date}` };
    }

    const overnight = (eMin <= sMin);
    const endYmd = overnight ? (_addDaysYmd(date, 1) || date) : date;

    if (tzId !== 'Europe/London') {
      const startUtcIso = _localYmdHmToUtcIso(date, startHH, tzId);
      const endUtcIso = _localYmdHmToUtcIso(endYmd, endHH, tzId);
      if (!startUtcIso) {
        return { startUtcIso: null, endUtcIso: null, error: `Invalid local start time on ${date}` };
      }
      if (!endUtcIso) {
        return { startUtcIso: null, endUtcIso: null, error: `Invalid local end time on ${date}` };
      }
      const startMs = new Date(startUtcIso).getTime();
      const endMs = new Date(endUtcIso).getTime();
      if (!Number.isFinite(startMs) || !Number.isFinite(endMs) || endMs <= startMs) {
        return { startUtcIso: null, endUtcIso: null, error: `Invalid local time range on ${date}` };
      }
      return {
        startUtcIso: new Date(startMs).toISOString(),
        endUtcIso: new Date(endMs).toISOString(),
        error: null
      };
    }

    const startCandidates = _uniqueLocalUtcCandidates(date, startHH);
    if (!startCandidates.length) {
      return { startUtcIso: null, endUtcIso: null, error: `Non-existent local start time on ${date}` };
    }

    const endCandidates = _uniqueLocalUtcCandidates(endYmd, endHH);
    if (!endCandidates.length) {
      return { startUtcIso: null, endUtcIso: null, error: `Non-existent local end time on ${endYmd}` };
    }

    const pairMap = new Map();

    const pushPair = (startIso, endIso) => {
      if (!startIso || !endIso) return;
      const startMs = new Date(startIso).getTime();
      const endMs = new Date(endIso).getTime();
      if (!Number.isFinite(startMs) || !Number.isFinite(endMs) || endMs <= startMs) return;
      const key = `${startMs}|${endMs}`;
      if (pairMap.has(key)) return;
      pairMap.set(key, {
        startUtcIso: new Date(startMs).toISOString(),
        endUtcIso: new Date(endMs).toISOString(),
        startMs,
        endMs
      });
    };

    for (const startCand of startCandidates) {
      const endIsoAfterStart = ukLocalToUtcISO(endYmd, endHH, { afterIso: startCand.iso, prefer: 'later' });
      pushPair(startCand.iso, endIsoAfterStart);
      for (const endCand of endCandidates) {
        pushPair(startCand.iso, endCand.iso);
      }
    }

    const pairs = Array.from(pairMap.values()).sort((a, b) => a.startMs - b.startMs || a.endMs - b.endMs);

    if (!pairs.length) {
      return { startUtcIso: null, endUtcIso: null, error: `Invalid local time range on ${date}` };
    }

    if (pairs.length > 1) {
      return { startUtcIso: null, endUtcIso: null, error: `Ambiguous local time range across DST change on ${date}` };
    }

    return {
      startUtcIso: pairs[0].startUtcIso,
      endUtcIso: pairs[0].endUtcIso,
      error: null
    };
  };

  // ─────────────────────────────────────────────────────────────
  // ✅ Reversal handling for correction timesheets (locked policy)
  // ─────────────────────────────────────────────────────────────
  const corrKindU = String(ts?.correction_kind || '').trim().toUpperCase();
  const adjOriginU = String(ts?.adjustment_origin || '').trim().toUpperCase();
  const isCorrection = !!corrKindU || adjOriginU === 'IMPORT_CORRECTION' || adjOriginU === 'IMPORT_CANCELLATION';
  const isReversal = isCorrection && corrKindU.includes('REVERSAL');
  const sign = isReversal ? -1 : 1;

  // ✅ Basis normalisation for correction timesheets:
  const boolishLocal = (v) => {
    if (v === true) return true;
    if (v === false) return false;
    if (v == null) return false;
    const s = String(v).trim().toLowerCase();
    return (s === 'true' || s === '1' || s === 'yes' || s === 'y' || s === 'on' || s === 't');
  };

  const routeTypeU = String(hr_eff_flags?.route_type || '').trim().toUpperCase();
  const isNhspRoute =
    routeTypeU === 'WEEKLY_NHSP' ||
    routeTypeU === 'WEEKLY_NHSP_ADJUSTMENT' ||
    boolishLocal(hr_eff_flags?.client_is_nhsp);

  const isHrRoute =
    routeTypeU === 'WEEKLY_HEALTHROSTER' ||
    boolishLocal(hr_eff_flags?.client_autoprocess_hr);

  const effective_basis = (() => {
    const cur = (curFin?.basis || 'CONTRACT_WEEKLY');
    const curU = String(cur).trim().toUpperCase();

    if (!isCorrection) return cur;

    if (isNhspRoute) {
      if (curU === 'NHSP' || curU === 'NHSP_ADJUSTMENT') return cur;
      return 'NHSP_ADJUSTMENT';
    }

    if (isHrRoute) {
      if (curU.startsWith('HEALTHROSTER')) return cur;
      return 'HEALTHROSTER_ADJUSTMENT';
    }

    return cur;
  })();

  const basisU = String(effective_basis || 'CONTRACT_WEEKLY').toUpperCase();
  const isHrCreateNoTs =
    (basisU === 'HEALTHROSTER_SELF_BILL' || basisU === 'HEALTHROSTER_ADJUSTMENT');

  const isAuthorised = !!(ts && ts.authorised_at_server);

  // ✅ QR unsigned gating (must block invoicing even if authorised)
  const qrStatusU = String(ts?.qr_status || '').trim().toUpperCase();
  const qrToken = (ts?.qr_token != null) ? String(ts.qr_token).trim() : '';
  const hasQrIssuedProof = (
    ((qrToken && !!ts?.qr_generated_at) === true) ||
    ((ts?.qr_last_sent_hash != null) && String(ts.qr_last_sent_hash).trim() !== '')
  );
  const qrAwaitingSignatureUpload =
    (qrStatusU === 'PENDING' && hasQrIssuedProof && !ts?.qr_scanned_at);

  // ✅ initial status (may be refined below after validation flags are evaluated)
  let processing_status = (qrAwaitingSignatureUpload)
    ? 'AWAITING_MANUAL_SIGNATURE'
    : ((!isAuthorised) ? 'PENDING_AUTH' : 'READY_FOR_INVOICE');

  // ✅ preserve expenses/mileage (+ units) from current snapshot (curFin)
  const expPay   = round2(asNumberLocal(curFin?.expenses_pay_ex_vat ?? 0));
  const expChg   = round2(asNumberLocal(curFin?.expenses_charge_ex_vat ?? 0));
  const milUnits = round2(asNumberLocal(curFin?.mileage_units ?? 0));
  const milPay   = round2(asNumberLocal(curFin?.mileage_pay_ex_vat ?? 0));
  const milChg   = round2(asNumberLocal(curFin?.mileage_charge_ex_vat ?? 0));

  const actualRaw = Array.isArray(ts?.actual_schedule_json) ? ts.actual_schedule_json : [];
  const actualNorm = normaliseScheduleBreakFields(actualRaw);

  // ✅ Determine whether we should override segment ref_num from imported HealthRoster shifts.
  const hrValidationRequired =
    boolishLocal(hr_eff_flags?.client_hr_validation_required) ||
    boolishLocal(hr_eff_flags?.hr_validation_required_for_invoice) ||
    false;

  const valStatusU = String(hr_validation_status || '').trim().toUpperCase();
  const valReasonU = String(hr_validation_reason_code || '').trim().toUpperCase();

  const isValidatedOk = hr_validation_source_kind === 'AGENCY_INVOICE_WEEK'
    ? valStatusU === 'VALIDATION_OK'
    : (valStatusU === 'VALIDATION_OK' || valStatusU === 'OVERRIDDEN' || valStatusU === 'OVERRIDE');

  const isWeeklyHrValidation = hr_validation_source_kind === 'AGENCY_INVOICE_WEEK'
    || ((!valReasonU) ? true : valReasonU.includes('HEALTHROSTER_WEEKLY'));

  const useImportRefs = !!(hrValidationRequired && isValidatedOk && isWeeklyHrValidation);

  // ✅ NEW: processing_status priority:
  // 1) QR awaiting signature => AWAITING_MANUAL_SIGNATURE (even if authorised)
  // 2) Not authorised => PENDING_AUTH
  // 3) HR validation required for invoice and NOT OK/OVERRIDDEN => READY_FOR_HR
  // 4) Else => READY_FOR_INVOICE
  if (qrAwaitingSignatureUpload) {
    processing_status = 'AWAITING_MANUAL_SIGNATURE';
  } else if (!isAuthorised) {
    processing_status = 'PENDING_AUTH';
  } else if (hrValidationRequired && !isValidatedOk && isWeeklyHrValidation) {
    processing_status = 'READY_FOR_HR';
  } else {
    processing_status = 'READY_FOR_INVOICE';
  }

  const parseUtcMs = (v) => {
    if (v == null) return null;
    let s = String(v).trim();
    if (!s) return null;
    if (/^\d{4}-\d{2}-\d{2}\s+\d{2}:\d{2}/.test(s) && !s.includes('T')) {
      s = s.replace(' ', 'T');
    }
    const d = new Date(s);
    if (Number.isNaN(d.getTime())) return null;
    return d.getTime();
  };

  // ✅ Build a fast lookup from imported HealthRoster shifts to their ref_num (Request Id)
  const hrRefByKey = new Map();     // `${date}|${startMs}|${endMs}` -> ref_num
  const hrListByDate = new Map();   // date -> [{ startMs, endMs, ref_num }]
  if (useImportRefs && Array.isArray(hr_preloaded_shifts) && hr_preloaded_shifts.length) {
    for (const sh of hr_preloaded_shifts) {
      const ss = String(sh?.source_system || '').trim().toUpperCase();
      if (ss !== 'HEALTHROSTER') continue;

      const d = sh?.work_date ? String(sh.work_date).slice(0, 10) : '';
      if (!/^\d{4}-\d{2}-\d{2}$/.test(d)) continue;

      const ref = (sh?.ref_num != null) ? String(sh.ref_num).trim() : '';
      if (!ref) continue;

      const sMs = parseUtcMs(sh?.start_utc);
      const eMs = parseUtcMs(sh?.end_utc);
      if (sMs == null || eMs == null) continue;

      const k = `${d}|${sMs}|${eMs}`;
      if (!hrRefByKey.has(k)) hrRefByKey.set(k, ref);

      if (!hrListByDate.has(d)) hrListByDate.set(d, []);
      hrListByDate.get(d).push({ startMs: sMs, endMs: eMs, ref_num: ref });
    }
  }

  // ✅ Preserve ref_num through normalisation (candidate-entered refs)
  const actual = (Array.isArray(actualNorm) ? actualNorm : []).map((seg, idx) => {
    if (!seg || typeof seg !== 'object') return seg;

    const raw = (Array.isArray(actualRaw) && actualRaw[idx] && typeof actualRaw[idx] === 'object')
      ? actualRaw[idx]
      : null;

    const v =
      seg.ref_num ?? seg.ref ?? seg.reference ?? seg.refNum ??
      raw?.ref_num ?? raw?.ref ?? raw?.reference ?? raw?.refNum ??
      null;

    const s = (v == null) ? '' : String(v).trim();
    const { start, end } = candidateScheduleLocalTimeAliases(seg, raw);

    return {
      ...seg,
      ...(start ? { start } : {}),
      ...(end ? { end } : {}),
      ...(s ? { ref_num: s } : {})
    };
  });

  if (!actual.length) {
    let policy_snapshot_json = {};
    if (policy_override && typeof policy_override === 'object') {
      policy_snapshot_json = policy_override;
    }

    const base_pay_ex_vat = 0;
    const base_charge_ex_vat = 0;
    const addl_pay_ex_vat = 0;
    const addl_charge_ex_vat = 0;

    const total_pay_ex_vat = round2(base_pay_ex_vat + addl_pay_ex_vat + expPay + milPay);
    const total_charge_ex_vat = round2(base_charge_ex_vat + addl_charge_ex_vat + expChg + milChg);

    const pol0 = (policy_override && typeof policy_override === 'object') ? policy_override : {};
    const applyTo0 = String(pol0.apply_erni_to || 'PAYE_ONLY').toUpperCase();
    const erniPctRaw0 = Number(pol0.erni_pct ?? 0);

    let erniMult0 = 1;
    if (Number.isFinite(erniPctRaw0) && erniPctRaw0 > 0) {
      const p = erniPctRaw0 > 1 ? (erniPctRaw0 / 100) : erniPctRaw0;
      erniMult0 = 1 + p;
    }

    const payMethodUpper0 = String(method || contract?.pay_method_snapshot || '').toUpperCase();
    const erniApplies0 =
      (applyTo0 === 'ALL') ||
      (applyTo0 === 'PAYE_ONLY' && payMethodUpper0 === 'PAYE');

    const payCostEx0 = round2(erniApplies0 ? (total_pay_ex_vat * erniMult0) : total_pay_ex_vat);
    const margin_ex_vat = round2(total_charge_ex_vat - payCostEx0);

    const snapshot = {
      timesheet_id: ts.timesheet_id,
      timesheet_version: ts.version || 1,
      basis: (effective_basis || 'CONTRACT_WEEKLY'),
      candidate_id: contract?.candidate_id || null,
      client_id: contract?.client_id || null,
      role: contract?.role || null,
      band: contract?.band || null,
      pay_method: method,
      policy_snapshot_json,
      rate_source_refs_json: { mode: 'CONTRACT_RATES_JSON', contract_id: contract?.id || null },

      hours_day: 0,
      hours_night: 0,
      hours_sat: 0,
      hours_sun: 0,
      hours_bh: 0,
      total_hours: 0,

      pay_day: pay.day, pay_night: pay.night, pay_sat: pay.sat, pay_sun: pay.sun, pay_bh: pay.bh,
      charge_day: chg.day, charge_night: chg.night, charge_sat: chg.sat, charge_sun: chg.sun, charge_bh: chg.bh,

      additional_units_json: {},
      additional_pay_ex_vat: 0,
      additional_charge_ex_vat: 0,
      additional_margin_ex_vat: 0,

      total_pay_ex_vat,
      total_charge_ex_vat,
      margin_ex_vat,

      expenses_pay_ex_vat: expPay,
      expenses_charge_ex_vat: expChg,
      expenses_description: curFin?.expenses_description ?? null,
      expenses_evidence_r2_key: curFin?.expenses_evidence_r2_key ?? null,
      expenses_evidence_manifest: curFin?.expenses_evidence_manifest ?? null,

      mileage_units: milUnits,
      mileage_pay_ex_vat: milPay,
      mileage_charge_ex_vat: milChg,
      mileage_evidence_r2_key: curFin?.mileage_evidence_r2_key ?? null,
      mileage_evidence_manifest: curFin?.mileage_evidence_manifest ?? null,
      mileage_pay_rate: curFin?.mileage_pay_rate ?? null,
      mileage_charge_rate: curFin?.mileage_charge_rate ?? null,

      candidate_assignment: (contract?.candidate_id ? 'ASSIGNED' : 'UNASSIGNED'),
      processing_status,

      invoice_breakdown_json: {
        mode: 'SEGMENTS',
        segments: [],
        totals: { total_pay_ex_vat, total_charge_ex_vat, margin_ex_vat }
      }
    };

    if (typeof enrichTsfinWithHrCrosscheck === 'function') {
      try { await enrichTsfinWithHrCrosscheck(env, ts, snapshot, hr_eff_flags || null, hr_preloaded_shifts || null); } catch {}
    }

    if (write_now) {
      if (!outbox_id) throw new Error('buildWeeklyScheduleSegmentsSnapshot: write_now requires options.outbox_id');
      const wr = await rpcTsfinWriteSnapshotsAndComplete(env, {
        rows: [{ outbox_id, timesheet_id: ts.timesheet_id, snapshot }]
      });
      return { ok: true, snapshot, write: wr };
    }

    return { ok: true, snapshot };
  }

  // ✅ Preserve locked segment evidence immutability (non-correction only)
  // Build lookups from existing snapshot segments.
  const preserved = new Map(); // stableKey -> { ... }
  const preservedBySegId = new Map(); // segment_id -> { ... }  ✅ (critical for legacy rows missing start/end fields)
  const preservedLockedByTime = new Map(); // `${date}|${startMs}|${endMs}` -> seg_obj

  try {
    const ib = curFin?.invoice_breakdown_json || null;
    const mode = String(ib?.mode || '').toUpperCase();
    const segs = Array.isArray(ib?.segments) ? ib.segments : null;

    if (mode === 'SEGMENTS' && segs) {
      for (const s of segs) {
        if (!s || typeof s !== 'object') continue;

        const segId0 = _normStr(s.segment_id);
        const key = _stableSegKey(s);

        const invLockRaw = (s.invoice_locked_invoice_id != null) ? String(s.invoice_locked_invoice_id).trim() : '';
        const isLocked = !!invLockRaw;

        const meta = {
          is_locked: isLocked,
          seg_obj: (isLocked ? s : null),
          exclude_from_pay: (typeof s.exclude_from_pay === 'boolean') ? s.exclude_from_pay : undefined,
          invoice_target_week_start: (s.invoice_target_week_start != null) ? String(s.invoice_target_week_start) : undefined,
          invoice_locked_invoice_id: (invLockRaw ? invLockRaw : undefined)
        };

        if (key) preserved.set(key, meta);
        if (segId0) preservedBySegId.set(segId0, meta);

        if (isLocked) {
          const d = (s?.date != null) ? String(s.date).slice(0, 10) : '';
          const sMs = parseUtcMs(s?.start_utc || s?.startUtc || null);
